// Content with portions generated by generative AI platform
package org.eclipse.kura.container.orchestration.provider.impl.enforcement;

import static org.junit.Assert.assertEquals;

import java.util.Set;

import org.junit.Test;

public class AllowlistTest {

    private static final String DIGEST = "sha256:aaa";
    private static final String OTHER_DIGEST = "sha256:bbb";
    private static final String THIRD_DIGEST = "sha256:ccc";

    private Allowlist allowlist;

    @Test
    public void eachLineIsAnAllowedDigest() {
        whenAllowlistIsParsed(DIGEST + "\n" + OTHER_DIGEST);

        thenAllowlistSizeIs(2);
        thenDigestsAllowingImageAre(Set.of(DIGEST, OTHER_DIGEST, THIRD_DIGEST), Set.of(DIGEST, OTHER_DIGEST));
    }

    @Test
    public void spacesAroundDigestsAreIgnored() {
        whenAllowlistIsParsed(" " + DIGEST + " \n " + OTHER_DIGEST + " ");

        thenDigestsAllowingImageAre(Set.of(DIGEST, OTHER_DIGEST), Set.of(DIGEST, OTHER_DIGEST));
    }

    @Test
    public void windowsAndClassicMacLineEndingsSeparateDigests() {
        whenAllowlistIsParsed(DIGEST + "\r\n" + OTHER_DIGEST + "\r" + THIRD_DIGEST);

        thenAllowlistSizeIs(3);
    }

    @Test
    public void emptyLinesAreIgnored() {
        whenAllowlistIsParsed(DIGEST + "\n\n\n" + OTHER_DIGEST + "\n");

        thenAllowlistSizeIs(2);
    }

    @Test
    public void emptyContentAllowsNothing() {
        whenAllowlistIsParsed("");

        thenAllowlistSizeIs(0);
        thenDigestsAllowingImageAre(Set.of(DIGEST), Set.of());
    }

    @Test
    public void onlyImageDigestsInTheAllowlistAllowTheImage() {
        whenAllowlistIsParsed(DIGEST + "\n" + OTHER_DIGEST);

        thenDigestsAllowingImageAre(Set.of(OTHER_DIGEST, THIRD_DIGEST), Set.of(OTHER_DIGEST));
    }

    private void whenAllowlistIsParsed(String content) {
        this.allowlist = Allowlist.parse(content);
    }

    private void thenAllowlistSizeIs(int expectedSize) {
        assertEquals(expectedSize, this.allowlist.size());
    }

    private void thenDigestsAllowingImageAre(Set<String> imageDigests, Set<String> expectedDigests) {
        assertEquals(expectedDigests, this.allowlist.digestsAllowing(imageDigests));
    }
}
